1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	/**
44	 * Added at the very end of every premium, after all percentage modifiers, so
45	 * no surcharge or discount is ever computed on top of it.
46	 */
47	const PROCESSING_FEE = 5;
48	
49	/**
50	 * Rates are kept as exact numerator/denominator fractions rather than float
51	 * multipliers (10 / 100, never 1.1) so intermediate amounts stay exact and
52	 * only the final premium is rounded.
53	 */
54	const percent = (amount: number, rate: number): number => (amount * rate) / 100;
55	
56	/**
57	 * Both roundings go the MHPCO's way, and both are applied once, at the very end
58	 * of a calculation — never to an intermediate amount. The two are stated here as
59	 * a pair because that is the rule: it is one policy with two directions, and
60	 * which direction applies follows from who pays.
61	 */
62	const roundedUpForWhatTheCustomerPays = Math.ceil;
63	const roundedDownForWhatTheMHPCOPays = Math.floor;
64	
65	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
66	const CURSE_SURCHARGE_PERCENT = 50;
67	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
68	/**
69	 * Enchantment is read by two unrelated rules with different cut-offs: this one
70	 * charges a premium surcharge from 5 up, and REDUCED_REIMBURSEMENT_THRESHOLD
71	 * halves a claim from 8 up. Each threshold is named after the rule it gates so
72	 * the two cannot be mistaken for one shared notion of "highly enchanted".
73	 */
74	const ENCHANTMENT_SURCHARGE_THRESHOLD = 5;
75	const LOYALTY_DISCOUNT_PERCENT = 20;
76	const LOYALTY_THRESHOLD_YEARS = 2;
77	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
78	
79	/**
80	 * Everything the pricing rules need to know about an item type lives here, so
81	 * that "what is a rune?" has a single answer. Components are the small parts
82	 * (runes, moonstones) that can be bought as a building block; main items
83	 * (swords, amulets, ...) never form a block.
84	 */
85	const ITEM_TYPES: Record<
86	  string,
87	  { unitPremium: number; insuranceValue: number; isComponent: boolean }
88	> = {
89	  sword: { unitPremium: 100, insuranceValue: 1000, isComponent: false },
90	  amulet: { unitPremium: 60, insuranceValue: 600, isComponent: false },
91	  staff: { unitPremium: 80, insuranceValue: 800, isComponent: false },
92	  potion: { unitPremium: 40, insuranceValue: 400, isComponent: false },
93	  rune: { unitPremium: 25, insuranceValue: 250, isComponent: true },
94	  moonstone: { unitPremium: 25, insuranceValue: 250, isComponent: true },
95	};
96	
97	/**
98	 * The single gate onto ITEM_TYPES, so that an item the MHPCO does not insure is
99	 * refused by name rather than surfacing as a stray TypeError somewhere downstream.
100	 */
101	const itemTypeOf = (type: string): (typeof ITEM_TYPES)[string] => {
102	  const itemType = ITEM_TYPES[type];
103	  if (itemType === undefined) {
104	    throw new Error(`unknown item type: ${type}`);
105	  }
106	  return itemType;
107	};
108	
109	/** A building block of 3 alike components is offered at this base premium. */
110	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
111	const COMPONENT_BLOCK_SIZE = 3;
112	
113	/**
114	 * Tallies how often each value occurs, e.g. ["rune", "rune"] → [["rune", 2]].
115	 *
116	 * Takes plain strings rather than items because both callers are counting a
117	 * type name, but reach it by different routes: a quote counts `item.type`, a
118	 * claim counts `damage.itemType`. Each caller projects its own key and this
119	 * stays ignorant of what the strings denote.
120	 */
121	const tally = (values: string[]): [string, number][] => {
122	  const counts = new Map<string, number>();
123	  for (const value of values) {
124	    counts.set(value, (counts.get(value) ?? 0) + 1);
125	  }
126	  return [...counts];
127	};
128	
129	const typesOf = (items: Item[]): string[] => items.map((item) => item.type);
130	
131	/**
132	 * Prices every item of one type together, because exactly 3 alike components
133	 * form a block charged as one. "Alike" means the same type, and the block does
134	 * not repeat: 4 or 7 runes are each priced per item.
135	 */
136	const basePremiumForType = (type: string, count: number): number => {
137	  const { unitPremium, isComponent } = itemTypeOf(type);
138	  return isComponent && count === COMPONENT_BLOCK_SIZE
139	    ? COMPONENT_BLOCK_BASE_PREMIUM
140	    : count * unitPremium;
141	};
142	
143	const sumOfBasePremiums = (items: Item[]): number =>
144	  tally(typesOf(items)).reduce(
145	    (sum, [type, count]) => sum + basePremiumForType(type, count),
146	    0,
147	  );
148	
149	/**
150	 * A rule whose rate is ADDED to those of every other matching rule. Read with
151	 * filter+reduce: matching several rules charges for each.
152	 *
153	 * Distinct from ExclusiveRule<T> below, which has the same {appliesTo, rate}
154	 * shape but the opposite semantics. The two are separate named types rather
155	 * than one shared shape so that the reader — and the compiler — cannot mistake
156	 * a stacking table for a first-match-wins one.
157	 */
158	interface StackingRule<T> {
159	  appliesTo: (subject: T) => boolean;
160	  rate: number;
161	}
162	
163	/**
164	 * What a stacking table charges against a base amount: every matching rule
165	 * contributes, so the rates add up rather than compete. This is the one place
166	 * the filter+reduce reading of StackingRule is performed — item surcharges and
167	 * policy adjustments are both this same idea, differing only in which table
168	 * they consult and what their percentages are taken of.
169	 */
170	const sumOfMatchingRates = <T>(
171	  rules: StackingRule<T>[],
172	  subject: T,
173	  base: number,
174	): number =>
175	  rules
176	    .filter(({ appliesTo }) => appliesTo(subject))
177	    .reduce((sum, { rate }) => sum + percent(base, rate), 0);
178	
179	/**
180	 * A rule that is an ALTERNATIVE to the others: the first match wins and the
181	 * rest are skipped. Read with find. Order is therefore meaningful — it encodes
182	 * precedence, and reordering the table changes results.
183	 */
184	interface ExclusiveRule<T> {
185	  appliesTo: (subject: T) => boolean;
186	  rate: number;
187	}
188	
189	/**
190	 * Item-specific modifiers: each applies to one item and is charged as a
191	 * percentage of THAT item's unit premium, never of the policy total.
192	 * They stack — an item matching several rules is charged for each.
193	 *
194	 * Unit premium, not the item's share of the policy base: the two differ only
195	 * for components inside a block of 3 (billed 60 G for three 25 G runes), and
196	 * no test pins down a surcharged component yet. Revisit when one does.
197	 */
198	const ITEM_MODIFIERS: StackingRule<Item>[] = [
199	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_PERCENT },
200	  {
201	    appliesTo: (item) =>
202	      (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_THRESHOLD,
203	    rate: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
204	  },
205	];
206	
207	const surchargeForItem = (item: Item): number =>
208	  sumOfMatchingRates(ITEM_MODIFIERS, item, itemTypeOf(item.type).unitPremium);
209	
210	const sumOfItemSurcharges = (items: Item[]): number =>
211	  items.reduce((sum, item) => sum + surchargeForItem(item), 0);
212	
213	/**
214	 * Policy-wide modifiers: each is charged as a percentage of the POLICY BASE
215	 * premium (the sum of item base premiums, before any item surcharge), so no
216	 * modifier is ever computed on top of another. Discounts carry a negative rate.
217	 */
218	interface PolicyContext {
219	  customer: Customer;
220	  /** Quotes already issued to this customer earlier in the scenario. */
221	  previousContracts: number;
222	}
223	
224	const POLICY_MODIFIERS: StackingRule<PolicyContext>[] = [
225	  // Always applies: every item in a quote is treated as a first insurance,
226	  // regardless of how long the customer has been with the MHPCO.
227	  { appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_PERCENT },
228	  {
229	    // Negative rate: a discount is just a surcharge pointing the other way, so
230	    // it needs no separate code path and cannot stack onto another modifier.
231	    appliesTo: ({ customer }) =>
232	      customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
233	    rate: -LOYALTY_DISCOUNT_PERCENT,
234	  },
235	  {
236	    appliesTo: ({ previousContracts }) => previousContracts >= 1,
237	    rate: -FOLLOW_UP_DISCOUNT_PERCENT,
238	  },
239	];
240	
241	const sumOfPolicyAdjustments = (
242	  context: PolicyContext,
243	  policyBasePremium: number,
244	): number =>
245	  sumOfMatchingRates(POLICY_MODIFIERS, context, policyBasePremium);
246	
247	const premiumFor = (context: PolicyContext, items: Item[]): number => {
248	  const policyBasePremium = sumOfBasePremiums(items);
249	  return roundedUpForWhatTheCustomerPays(
250	    policyBasePremium +
251	      sumOfItemSurcharges(items) +
252	      sumOfPolicyAdjustments(context, policyBasePremium) +
253	      PROCESSING_FEE,
254	  );
255	};
256	
257	/** A policy created by a quote step, tracked so later claims can draw on it. */
258	interface Policy {
259	  items: Item[];
260	  remainingCap: number;
261	}
262	
263	const DEDUCTIBLE_PER_DAMAGE = 100;
264	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
265	
266	const insuranceSumOf = (items: Item[]): number =>
267	  items.reduce((sum, item) => sum + itemTypeOf(item.type).insuranceValue, 0);
268	
269	const REDUCED_REIMBURSEMENT_THRESHOLD = 8;
270	const REDUCED_REIMBURSEMENT_PERCENT = 50;
271	
272	/** Reimbursed in full when no clause below claims the item. */
273	const FULL_REIMBURSEMENT_PERCENT = 100;
274	const DRAGON_MATERIAL = "dragon";
275	
276	/**
277	 * Clauses that change how much of a damage is reimbursed. Exclusive and ordered
278	 * by precedence, because clauses overlap (a highly enchanted dragon-material
279	 * item matches more than one) and they are alternatives — unlike the stacking
280	 * ITEM_MODIFIERS, which the {appliesTo, rate} shape would otherwise suggest.
281	 */
282	const REIMBURSEMENT_CLAUSES: ExclusiveRule<Item>[] = [
283	  {
284	    appliesTo: (item) =>
285	      (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_THRESHOLD,
286	    rate: REDUCED_REIMBURSEMENT_PERCENT,
287	  },
288	  // Listed after the clause above so that a highly enchanted dragon item is
289	  // still reimbursed at 50 %. This entry yields exactly what the no-clause
290	  // default yields, so removing it would not change any current result — it is
291	  // here because the spec states dragon material as a rule, and because the
292	  // ordering is what makes the 50 % rule win.
293	  {
294	    appliesTo: (item) => item.material === DRAGON_MATERIAL,
295	    rate: FULL_REIMBURSEMENT_PERCENT,
296	  },
297	];
298	
299	const reimbursementRateFor = (item: Item): number =>
300	  REIMBURSEMENT_CLAUSES.find(({ appliesTo }) => appliesTo(item))?.rate ??
301	  FULL_REIMBURSEMENT_PERCENT;
302	
303	/**
304	 * The one phrasing of "the policy does not cover that". Both the whole-claim
305	 * check and the per-damage lookup below can raise it, so the wording lives in
306	 * one place rather than being written out at each site.
307	 *
308	 * A damage naming a type the MHPCO does not insure at all is this same refusal:
309	 * it is not in the policy either, so it needs no rule of its own.
310	 */
311	const notCoveredByPolicy = (itemType: string): Error =>
312	  new Error(`damaged item is not covered by the policy: ${itemType}`);
313	
314	/**
315	 * Which insured item a damage entry is about. The counterpart to itemTypeOf:
316	 * both resolve a name to the thing it denotes.
317	 *
318	 * The not-found branch is unreachable for any damage that got past
319	 * assertDamagesAreCovered, which rejects uncovered types before a payout is
320	 * computed. It stays because `find` returns `Item | undefined` and the type has
321	 * to be honoured — but the rule it enforces is stated there, not here, so this
322	 * reuses that refusal instead of restating it.
323	 */
324	const insuredItemFor = (damage: Damage, insuredItems: Item[]): Item => {
325	  const insuredItem = insuredItems.find(
326	    (item) => item.type === damage.itemType,
327	  );
328	  if (insuredItem === undefined) {
329	    throw notCoveredByPolicy(damage.itemType);
330	  }
331	  return insuredItem;
332	};
333	
334	/**
335	 * The clause is applied to the damage first; the deductible comes off whatever
336	 * the clause leaves.
337	 *
338	 * Takes the already-resolved item, so this is pure arithmetic over a damage and
339	 * the item it hit — mirroring basePremiumForType, which likewise prices an
340	 * already-resolved type rather than doing its own lookup.
341	 */
342	const payoutForDamage = (damage: Damage, damagedItem: Item): number =>
343	  percent(damage.amount, reimbursementRateFor(damagedItem)) -
344	  DEDUCTIBLE_PER_DAMAGE;
345	
346	/**
347	 * The contract a quote step issues: what it covers, and how much of its cap is
348	 * still available to later claims.
349	 */
350	const policyFor = (items: Item[]): Policy => ({
351	  items,
352	  remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items),
353	});
354	
355	/**
356	 * What an incident is worth against a policy, as a pure calculation: each
357	 * damage is settled on its own (own clause, own deductible) and the results are
358	 * added up. Drawing this down from the policy's cap is the caller's job.
359	 */
360	const payoutForIncident = (
361	  incident: ClaimStep["incident"],
362	  insuredItems: Item[],
363	): number =>
364	  incident.damages.reduce(
365	    (sum, damage) =>
366	      sum + payoutForDamage(damage, insuredItemFor(damage, insuredItems)),
367	    0,
368	  );
369	
370	/**
371	 * A policy covering one sword cannot answer for two damaged swords. Checked
372	 * before anything is paid, because the whole claim is rejected rather than
373	 * settled as far as the cover reaches.
374	 */
375	const assertDamagesAreCovered = (
376	  damages: Damage[],
377	  insuredItems: Item[],
378	): void => {
379	  const insuredCounts = new Map(tally(typesOf(insuredItems)));
380	  for (const [itemType, damaged] of tally(
381	    damages.map((damage) => damage.itemType),
382	  )) {
383	    const insured = insuredCounts.get(itemType) ?? 0;
384	    if (insured === 0) {
385	      throw notCoveredByPolicy(itemType);
386	    }
387	    if (damaged > insured) {
388	      throw new Error(`more ${itemType} damages than the policy covers`);
389	    }
390	  }
391	};
392	
393	/**
394	 * Settles an incident against a policy and draws the payout down from its cap.
395	 * Mutates the policy, because what this claim consumes has to be visible to
396	 * every later claim on the same one.
397	 *
398	 * The cap is a ceiling, not just a running total: once it is exhausted a claim
399	 * is paid only what is left of it. Rounding happens once, here, after the clamp
400	 * — so per-damage amounts stay fractional (a multi-item incident is not rounded
401	 * once per damage) and the cap stays whole.
402	 */
403	/**
404	 * A negative damage would be a negative payout, which the drawdown would then
405	 * SUBTRACT from the remaining cap — letting a claim enlarge the very cover it
406	 * draws on. Refused outright rather than clamped to zero.
407	 */
408	const assertDamageAmountsArePositive = (damages: Damage[]): void => {
409	  for (const { amount } of damages) {
410	    if (amount < 0) {
411	      throw new Error(`negative damage amount: ${amount}`);
412	    }
413	  }
414	};
415	
416	const settleClaim = (
417	  policy: Policy,
418	  incident: ClaimStep["incident"],
419	): StepResult => {
420	  assertDamageAmountsArePositive(incident.damages);
421	  assertDamagesAreCovered(incident.damages, policy.items);
422	  const payout = roundedDownForWhatTheMHPCOPays(
423	    Math.min(payoutForIncident(incident, policy.items), policy.remainingCap),
424	  );
425	  policy.remainingCap -= payout;
426	  return { payout, remainingCap: policy.remainingCap };
427	};
428	
429	/**
430	 * Steps are executed in order because a step's result can depend on the ones
431	 * before it: the count of contracts already issued decides the follow-up
432	 * discount, and the policies a quote registers are what later claims draw on.
433	 */
434	export const runScenario = (scenario: Scenario): ScenarioResult => {
435	  let previousContracts = 0;
436	  const policies = new Map<number, Policy>();
437	
438	  const results = scenario.steps.map((step, index): StepResult => {
439	    if (step.op === "claim") {
440	      // Unguarded: no test yet describes a claim naming a policy that was never
441	      // quoted. The "claim references an item/policy not in the policy" test
442	      // will force this honest.
443	      const policy = policies.get(step.policy) as Policy;
444	      return settleClaim(policy, step.incident);
445	    }
446	
447	    const premium = premiumFor(
448	      { customer: scenario.customer, previousContracts },
449	      step.items,
450	    );
451	    policies.set(index, policyFor(step.items));
452	    // Counted after pricing, so a quote never discounts itself, and only for
453	    // quotes, because a claim does not issue a contract.
454	    previousContracts += 1;
455	    return { premium };
456	  });
457	  return { results };
458	};
