95	  it("quotes 7 runes — 175 G base premium, no block (+ 17.5 first insurance + 5 fee = 197.5 → 198 G)", () => {
96	    const result = runScenario({
97	      customer: { yearsWithMHPCO: 0 },
98	      steps: [
99	        {
100	          op: "quote",
101	          items: Array.from({ length: 7 }, () => ({ type: "rune" })),
102	        },
103	      ],
104	    });
105	
106	    expect(result).toEqual({ results: [{ premium: 198 }] });
107	  });
108	  it("quotes 2 runes + 1 moonstone — 75 G base premium, no block since types differ (+ 7.5 first insurance + 5 fee = 87.5 → 88 G)", () => {
109	    const result = runScenario({
110	      customer: { yearsWithMHPCO: 0 },
111	      steps: [
112	        {
113	          op: "quote",
114	          items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
115	        },
116	      ],
