121	  it("quotes 3 runes + 3 moonstones — 120 G base premium, two separate blocks (+ 12 first insurance + 5 fee = 137 G)", () => {
122	    const result = runScenario({
123	      customer: { yearsWithMHPCO: 0 },
124	      steps: [
125	        {
126	          op: "quote",
127	          items: [
128	            { type: "rune" },
129	            { type: "rune" },
130	            { type: "rune" },
131	            { type: "moonstone" },
132	            { type: "moonstone" },
133	            { type: "moonstone" },
134	          ],
135	        },
136	      ],
137	    });
138	
139	    expect(result).toEqual({ results: [{ premium: 137 }] });
140	  });
141	
